python -c "
import ast, pathlib
banned_imports={'subprocess','socket','httpx','requests','urllib','importlib'}
banned_calls={'eval','exec','system','popen'}
bad=[]
for p in pathlib.Path('app/toolbox').rglob('*.py'):
    t=ast.parse(p.read_text())
    for n in ast.walk(t):
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.name.split('.')[0] in banned_imports: bad.append((str(p), a.name))
        elif isinstance(n, ast.ImportFrom):
            if (n.module or '').split('.')[0] in banned_imports: bad.append((str(p), n.module))
        elif isinstance(n, ast.Call):
            f=n.func
            if isinstance(f, ast.Name) and f.id in banned_calls: bad.append((str(p), f.id))
            if isinstance(f, ast.Attribute) and f.attr=='load' and isinstance(f.value, ast.Name) and f.value.id=='yaml': bad.append((str(p), 'yaml.load'))
assert not bad, bad
"
